    // Render Tabel & Analitik Rekapitulasi Data
    function renderTahfidzRekapTable() {
      let data = [];
      try {
        data = JSON.parse(localStorage.getItem('tahfidz_rekap_db') || '[]');
      } catch (e) {
        data = [];
      }

      const totalStat = document.getElementById('tahfidzStatTotal');
      const mumtazStat = document.getElementById('tahfidzStatMumtaz');
      const topUnitStat = document.getElementById('tahfidzStatTopUnit');
      const tbody = document.getElementById('tahfidzRekapTableBody');
      const emptyState = document.getElementById('tahfidzRekapEmptyState');

      // Update Analytics
      if (totalStat) totalStat.innerText = `${data.length} Santri`;

      const mumtazCount = data.filter(d => d.predikat === 'Mumtaz').length;
      if (mumtazStat) mumtazStat.innerText = `${mumtazCount} Santri`;

      if (topUnitStat) {
        if (data.length === 0) {
          topUnitStat.innerText = '-';
        } else {
          const unitCounts = {};
          data.forEach(d => {
            unitCounts[d.unit] = (unitCounts[d.unit] || 0) + 1;
          });
          let maxUnit = '-';
          let maxCount = 0;
          for (const u in unitCounts) {
            if (unitCounts[u] > maxCount) {
              maxCount = unitCounts[u];
              maxUnit = `${u} (${maxCount})`;
            }
          }
          topUnitStat.innerText = maxUnit;
        }
      }

      // Render Table Rows
      if (!tbody) return;

      if (data.length === 0) {
        tbody.innerHTML = '';
        if (emptyState) emptyState.classList.remove('hidden');
        return;
      }

      if (emptyState) emptyState.classList.add('hidden');

      let rowsHtml = '';
      data.forEach((item, idx) => {
        const dateObj = new Date(item.savedAt || Date.now());
        const dateStr = dateObj.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) + ' ' +
                        dateObj.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

        const isPutri = item.gender === 'Putri';
        const genderBadgeClass = isPutri 
          ? 'bg-pink-100 dark:bg-pink-950/70 text-pink-700 dark:text-pink-300 border-pink-200 dark:border-pink-800/60' 
          : 'bg-blue-100 dark:bg-blue-950/70 text-blue-700 dark:text-sky-300 border-blue-200 dark:border-blue-800/60';

        let predikatBadge = '';
        if (item.predikat === 'Mumtaz') {
          predikatBadge = '<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/70 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-800/60">🌟 Mumtaz</span>';
        } else if (item.predikat === 'Jayyid Jiddan') {
          predikatBadge = '<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 dark:bg-blue-950/70 text-blue-800 dark:text-sky-300 border border-blue-300 dark:border-blue-800/60">Jayyid Jiddan</span>';
        } else if (item.predikat === 'Jayyid') {
          predikatBadge = '<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/70 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800/60">Jayyid</span>';
        } else {
          predikatBadge = `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700">${item.predikat || 'Jayyid'}</span>`;
        }

        rowsHtml += `
          <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition-colors">
            <td class="py-2.5 px-3 text-center font-bold text-slate-400">${idx + 1}</td>
            <td class="py-2.5 px-3 text-[11px] text-slate-500 dark:text-slate-400 whitespace-nowrap">${dateStr}</td>
            <td class="py-2.5 px-3">
              <div class="flex items-center gap-1.5 flex-wrap">
                <span class="font-bold text-slate-800 dark:text-white">${item.nama}</span>
                <span class="text-[9px] font-bold px-1.5 py-0.2 rounded border ${genderBadgeClass}">${item.gender}</span>
              </div>
            </td>
            <td class="py-2.5 px-3 text-center">
              <span class="font-bold text-[11px] px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                ${item.unit}
              </span>
              <div class="text-[10px] text-slate-400 mt-0.5">${item.kelas || ''}</div>
            </td>
            <td class="py-2.5 px-3 text-[11px]">
              <div>Bpk: <b>${item.bapak}</b></div>
              <div>Ibu: <b>${item.ibu}</b></div>
            </td>
            <td class="py-2.5 px-3">
              <span class="font-bold text-emerald-700 dark:text-emerald-400 text-xs">${item.juz}</span>
              <div class="text-[10px] text-slate-400">${item.kategori}</div>
            </td>
            <td class="py-2.5 px-3 text-center whitespace-nowrap">${predikatBadge}</td>
            <td class="py-2.5 px-3 text-center">
              <div class="flex items-center justify-center gap-1">
                <button 
                  type="button" 
                  onclick="loadRekapToTahfidzForm('${item.id}')" 
                  class="p-1.5 rounded-lg text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-950/50 transition-colors cursor-pointer" 
                  title="Muat data santri ini kembali ke formulir"
                >
                  <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
                </button>
                <button 
                  type="button" 
                  onclick="deleteTahfidzRekapItem('${item.id}')" 
                  class="p-1.5 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/50 transition-colors cursor-pointer" 
                  title="Hapus baris ini"
                >
                  <i data-lucide="trash" class="w-3.5 h-3.5"></i>
                </button>
              </div>
            </td>
          </tr>
        `;
      });

      tbody.innerHTML = rowsHtml;
      safeCreateIcons();
    }

    // Hapus Baris Rekap
    function deleteTahfidzRekapItem(id) {
      if (!confirm('Hapus data rekap santri ini?')) return;
      try {
        let stored = JSON.parse(localStorage.getItem('tahfidz_rekap_db') || '[]');
        stored = stored.filter(item => item.id !== id);
        localStorage.setItem('tahfidz_rekap_db', JSON.stringify(stored));
        updateTahfidzRekapBadgeCount();
        renderTahfidzRekapTable();
        if (typeof showToast === 'function') {
          showToast('Data rekap berhasil dihapus.');
        }
      } catch (e) {
        console.error('Error deleting rekap item:', e);
      }
    }

    // Bersihkan Semua Rekap
    function clearAllTahfidzRekap() {
      if (!confirm('Apakah Anda yakin ingin menghapus SEMUA riwayat rekap data tahfidz? Tindakan ini tidak dapat dibatalkan.')) return;
      try {
        localStorage.removeItem('tahfidz_rekap_db');
        updateTahfidzRekapBadgeCount();
        renderTahfidzRekapTable();
        if (typeof showToast === 'function') {
          showToast('Semua riwayat rekap data tahfidz telah dibersihkan.');
        }
      } catch (e) {
        console.error('Error clearing rekap:', e);
      }
    }

    // Ekspor ke CSV
    function exportTahfidzToCsv() {
      let data = [];
      try {
        data = JSON.parse(localStorage.getItem('tahfidz_rekap_db') || '[]');
      } catch (e) {
        data = [];
      }

      if (data.length === 0) {
        alert('Tidak ada data rekap untuk diekspor!');
        return;
      }

      const headers = ['No', 'Waktu Simpan', 'Nama Santri', 'Gender', 'Unit', 'Kelas', 'Nama Bapak', 'Nama Ibu', 'Kategori', 'Juz Diujikan', 'Predikat'];
      const rows = [headers.join(',')];

      data.forEach((d, idx) => {
        const dateObj = new Date(d.savedAt || Date.now());
        const dateStr = dateObj.toLocaleDateString('id-ID') + ' ' + dateObj.toLocaleTimeString('id-ID');
        const escapeCsv = (str) => `"${String(str || '').replace(/"/g, '""')}"`;

        const row = [
          idx + 1,
          escapeCsv(dateStr),
          escapeCsv(d.nama),
          escapeCsv(d.gender),
          escapeCsv(d.unit),
          escapeCsv(d.kelas),
          escapeCsv(d.bapak),
          escapeCsv(d.ibu),
          escapeCsv(d.kategori),
          escapeCsv(d.juz),
          escapeCsv(d.predikat)
        ];
        rows.push(row.join(','));
      });

      // Prepend UTF-8 BOM for MS Excel compatibility
      const csvContent = '\uFEFF' + rows.join('\r\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const now = new Date();
      const filename = `Rekap_Tahfidz_Tasmi_YTPAI_${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}_${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}.csv`;

      link.setAttribute('href', url);
      link.setAttribute('download', filename);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      if (typeof showToast === 'function') {
        showToast('File CSV berhasil diunduh!');
      }
    }

    // Reset Form Input
    function resetTahfidzForm() {
      const inputs = ['tahfidzNama', 'tahfidzKelas', 'tahfidzBapak', 'tahfidzIbu', 'tahfidzKategori', 'tahfidzJuz', 'tahfidzSearchInput'];
      inputs.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
      });
      const unitEl = document.getElementById('tahfidzUnit');
      if (unitEl) unitEl.value = 'MA';

      const activeBadge = document.getElementById('tahfidzActiveStudentBadge');
      if (activeBadge) activeBadge.innerText = 'Belum Ada Santri';

      setTahfidzGender('Putra');
      setTahfidzPredikat('Mumtaz');
      clearTahfidzSearch();
      updateTahfidzCaptionPreview();

      if (typeof showToast === 'function') {
        showToast('Formulir berhasil dikosongkan.');
      }
    }

    // =========================================================================
    // VOICE RECOGNITION & SMART NLP COMMAND PARSER UNTUK TAHFIDZ & TASMI'
    // =========================================================================
    let tahfidzSpeechRecognitionInstance = null;
    let isTahfidzVoiceListening = false;

    function toggleTahfidzVoiceRecognition() {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (!SpeechRecognition) {
        if (typeof showToast === 'function') {
          showToast('Fitur Suara Tidak Didukung', 'Browser Anda belum mendukung Web Speech Recognition. Silakan gunakan Google Chrome di HP/Laptop.', 'warning');
        } else {
          alert('Browser ini belum mendukung Web Speech Recognition. Silakan gunakan Google Chrome.');
        }
        return;
      }

      if (isTahfidzVoiceListening) {
        stopTahfidzVoiceRecognition();
      } else {
        startTahfidzVoiceRecognition(SpeechRecognition);
      }
    }

    function startTahfidzVoiceRecognition(SpeechRecognition) {
      try {
        tahfidzSpeechRecognitionInstance = new SpeechRecognition();
        tahfidzSpeechRecognitionInstance.lang = 'id-ID';
        tahfidzSpeechRecognitionInstance.continuous = false;
        tahfidzSpeechRecognitionInstance.interimResults = true;

        const voiceBtn = document.getElementById('tahfidzVoiceBtn');
        const voiceLabel = document.getElementById('tahfidzVoiceBtnLabel');
        const listeningBanner = document.getElementById('tahfidzVoiceListeningBanner');
        const liveTranscript = document.getElementById('tahfidzVoiceLiveTranscript');

        let commandProcessed = false;
        let lastRecognizedText = '';

        tahfidzSpeechRecognitionInstance.onstart = function() {
          isTahfidzVoiceListening = true;
          commandProcessed = false;
          lastRecognizedText = '';
          if (voiceBtn) {
            voiceBtn.className = 'px-2 py-1 bg-red-600 hover:bg-red-700 active:scale-95 text-white rounded-md text-[11px] font-bold flex items-center gap-1 shadow-md cursor-pointer transition-all border border-red-500 animate-pulse ring-2 ring-red-400';
          }
          if (voiceLabel) voiceLabel.textContent = 'Mendengarkan...';
          if (listeningBanner) listeningBanner.classList.remove('hidden');
          if (liveTranscript) liveTranscript.textContent = 'Silakan sebutkan nama santri, juz, & predikat (cth: "Fahri juz 30 mumtaz")...';
        };

        tahfidzSpeechRecognitionInstance.onresult = function(event) {
          let interimTranscript = '';
          let finalTranscript = '';

          for (let i = event.resultIndex; i < event.results.length; ++i) {
            if (event.results[i].isFinal) {
              finalTranscript += event.results[i][0].transcript;
            } else {
              interimTranscript += event.results[i][0].transcript;
            }
          }

          const currentText = (finalTranscript || interimTranscript).trim();
          if (currentText) {
            lastRecognizedText = currentText;
          }
          if (liveTranscript && currentText) {
            liveTranscript.textContent = `🗣️ "${currentText}"`;
          }

          if (finalTranscript && finalTranscript.trim().length > 1) {
            commandProcessed = true;
            processTahfidzSmartCommand(finalTranscript.trim());
            stopTahfidzVoiceRecognition();
          }
        };

        tahfidzSpeechRecognitionInstance.onerror = function(event) {
          console.warn('Voice Recognition Error:', event.error);
          stopTahfidzVoiceRecognition();
          if (event.error === 'not-allowed') {
            if (typeof showToast === 'function') {
              showToast('Izin Mikrofon Ditolak', 'Mohon izinkan akses mikrofon di pengaturan browser Anda.', 'error');
            }
          } else if (event.error !== 'no-speech' && typeof showToast === 'function') {
            showToast('Suara Tidak Terdeteksi', 'Coba ulangi berbicara lebih dekat ke mikrofon.', 'warning');
          }
        };

        tahfidzSpeechRecognitionInstance.onend = function() {
          if (!commandProcessed && lastRecognizedText && lastRecognizedText.length > 1) {
            commandProcessed = true;
            processTahfidzSmartCommand(lastRecognizedText);
          }
          stopTahfidzVoiceRecognition();
        };

        tahfidzSpeechRecognitionInstance.start();
      } catch (e) {
        console.error('Start Voice Recognition Failed:', e);
        stopTahfidzVoiceRecognition();
      }
    }

    function stopTahfidzVoiceRecognition() {
      isTahfidzVoiceListening = false;
      if (tahfidzSpeechRecognitionInstance) {
        try { tahfidzSpeechRecognitionInstance.stop(); } catch (e) {}
        tahfidzSpeechRecognitionInstance = null;
      }

      const voiceBtn = document.getElementById('tahfidzVoiceBtn');
      const voiceLabel = document.getElementById('tahfidzVoiceBtnLabel');
      const listeningBanner = document.getElementById('tahfidzVoiceListeningBanner');

      if (voiceBtn) {
        voiceBtn.className = 'px-2 py-1 bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white rounded-md text-[11px] font-bold flex items-center gap-1 shadow-2xs cursor-pointer transition-all border border-emerald-500';
      }
      if (voiceLabel) voiceLabel.textContent = 'Suara';
      if (listeningBanner) listeningBanner.classList.add('hidden');
    }

    function handleTahfidzSearchKeydown(e, val) {
      if (e.key === 'Enter') {
        e.preventDefault();
        const dropdown = document.getElementById('tahfidzSearchDropdown');
        if (dropdown) dropdown.classList.add('hidden');
        processTahfidzSmartCommand(val);
      }
    }

    function processTahfidzSmartCommand(rawText) {
      if (!rawText || !rawText.trim()) return false;
      const originalText = rawText.trim();

      // Check for global tab navigation command first
      if (typeof SmartVoiceNLP !== 'undefined' && SmartVoiceNLP.dispatchSmartVoiceCommand) {
        const norm = SmartVoiceNLP.normalizeText(originalText);
        const clean = SmartVoiceNLP.stripFillers(norm);
        if (/\b(buka|pindah|tampilkan|ke|menu|tab)\b/i.test(clean) && !/\b(juz|predikat|mumtaz|jayyid|tasmi)\b/i.test(clean)) {
          if (SmartVoiceNLP.dispatchSmartVoiceCommand(originalText)) return true;
        }
      }

      const masterStudents = getTahfidzMasterStudents();
      const parsed = typeof SmartVoiceNLP !== 'undefined' 
        ? SmartVoiceNLP.parseTahfidzIntent(originalText, masterStudents)
        : null;

      let matchedStudent = parsed ? parsed.matchedStudent : null;
      let detectedJuz = parsed ? parsed.detectedJuz : null;
      let detectedKategori = parsed ? parsed.detectedKategori : null;
      let detectedPredikat = parsed ? parsed.detectedPredikat : null;

      // Fallback student if none matched
      if (!matchedStudent) {
        matchedStudent = masterStudents.find(s => s.id === currentTahfidzStudentId) || masterStudents[0];
      }

      if (matchedStudent) {
        // 1. Pilih santri dan isi form
        selectTahfidzStudent(matchedStudent.id);

        // 2. Set Juz & Kategori jika terdeteksi
        if (detectedJuz) {
          const juzEl = document.getElementById('tahfidzJuz');
          if (juzEl) juzEl.value = detectedJuz;
        }
        if (detectedKategori) {
          const katEl = document.getElementById('tahfidzKategori');
          if (katEl) katEl.value = detectedKategori;
        }

        // 3. Set Predikat jika terdeteksi
        if (detectedPredikat) {
          setTahfidzPredikat(detectedPredikat);
        }

        // 4. Update preview caption
        updateTahfidzCaptionPreview();

        // 5. Feedback visual & audio ke user
        const finalJuz = detectedJuz || matchedStudent.defaultJuz || '30';
        const finalPredikat = detectedPredikat || currentTahfidzPredikat || 'Mumtaz';

        const searchInput = document.getElementById('tahfidzSearchInput');
        if (searchInput) {
          searchInput.value = `${matchedStudent.nama} (${matchedStudent.unit}) - Juz ${finalJuz} - ${finalPredikat}`;
        }

        const spokenAns = `Data ananda ${matchedStudent.nama} unit ${matchedStudent.unit} terpilih. Juz ${finalJuz}, predikat ${finalPredikat}. Siap dibagikan.`;
        if (typeof speakHumasAnswer === 'function') {
          speakHumasAnswer(spokenAns);
        }

        if (typeof showToast === 'function') {
          showToast(`🎯 Santri: ${matchedStudent.nama}`, `Juz ${finalJuz} • ${finalPredikat} (${matchedStudent.unit})`, 'success');
        }
        return true;
      }
      return false;
    }

    // ==============================================================
    // 14.6 PROGRESSIVE WEB APP (PWA) INSTALLATION & WORKER ENGINE
    // ==============================================================
    let deferredPwaPrompt = null;

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      deferredPwaPrompt = e;
      const installBtn = document.getElementById('pwaInstallBtn');
      if (installBtn) installBtn.classList.remove('hidden');
    });

    window.addEventListener('appinstalled', () => {
      deferredPwaPrompt = null;
      const installBtn = document.getElementById('pwaInstallBtn');
      if (installBtn) installBtn.classList.add('hidden');
      if (typeof showToast === 'function') {
        showToast('Aplikasi Terpasang!', 'Partner Fatih YTPAI telah berhasil dipasang di layar utama perangkat Anda.');
      }
    });

    function checkStandalonePwa() {
      if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) {
        const installBtn = document.getElementById('pwaInstallBtn');
        if (installBtn) installBtn.classList.add('hidden');
      }
    }
    checkStandalonePwa();
    window.addEventListener('DOMContentLoaded', checkStandalonePwa);

        function triggerPwaInstall() {
      if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true) {
        if (typeof showToast === 'function') {
          showToast('Sudah Terpasang', 'Partner Fatih sudah aktif dalam mode aplikasi mandiri di perangkat Anda.');
        } else {
          alert('Partner Fatih sudah aktif dalam mode aplikasi mandiri di perangkat Anda.');
        }
        return;
      }
      if (deferredPwaPrompt) {
        deferredPwaPrompt.prompt();
        deferredPwaPrompt.userChoice.then((choiceResult) => {
          if (choiceResult.outcome === 'accepted') {
            if (typeof showToast === 'function') {
              showToast('Memasang Aplikasi...', 'Partner Fatih sedang ditambahkan ke layar utama perangkat Anda.');
            }
          }
          deferredPwaPrompt = null;
        });
      } else {
        if (typeof showToast === 'function') {
          showToast("Pasang Aplikasi", 'Tekan menu browser (titik tiga) lalu pilih "Tambahkan ke Layar Utama" / "Install App".');
        } else {
          alert('Untuk memasang di HP atau desktop, buka menu browser (titik tiga) lalu pilih "Tambahkan ke Layar Utama" / "Install App".');
        }
      }
    }

    // ==========================================================================
    // GLOBAL MASTER SYNC: SINKRONISASI SATU KLIK SELURUH TAB & CLOUD SUPABASE
    // ==========================================================================
    window.triggerMasterSync = async function() {
      const btn = document.getElementById('masterSyncBtn');
      const icon = document.getElementById('masterSyncIcon');
      if (icon) icon.classList.add('animate-spin');
      if (btn) btn.disabled = true;

      if (typeof showToast === 'function') {
        showToast('Memulai Sinkronisasi', 'Menyelaraskan seluruh tab, jadwal resmi Kode 33, dan data Cloud Supabase...');
      }

      const summary = [];

      // 1. Sinkronisasi Tab Jurnal (Kode 33 Prakarya & Kalibrasi Jam Bel Resmi)
      try {
        if (typeof DEFAULT_SCHEDULES !== 'undefined' && typeof DEFAULT_CLASS_SCHEDULE !== 'undefined') {
          const stored = localStorage.getItem('partner_fatih_jurnal_state_v1');
          let state = stored ? JSON.parse(stored) : null;
          if (!state) state = { classes: {}, schedules: [] };
          
          // Force update schedules to official Kode 33
          state.schedules = JSON.parse(JSON.stringify(DEFAULT_SCHEDULES));

          // Force update 7A-7D
          const studentMap = {
            '7A': typeof DEFAULT_STUDENTS_7A !== 'undefined' ? DEFAULT_STUDENTS_7A : [],
            '7B': typeof DEFAULT_STUDENTS_7B !== 'undefined' ? DEFAULT_STUDENTS_7B : [],
            '7C': typeof DEFAULT_STUDENTS_7C !== 'undefined' ? DEFAULT_STUDENTS_7C : [],
            '7D': typeof DEFAULT_STUDENTS_7D !== 'undefined' ? DEFAULT_STUDENTS_7D : []
          };
          
          ['7A', '7B', '7C', '7D'].forEach(cId => {
            if (!state.classes[cId] && typeof createInitialClassData === 'function') {
              state.classes[cId] = createInitialClassData('formal', 'Prakarya (Kode 33)', cId, studentMap[cId]);
            } else if (state.classes[cId]) {
              state.classes[cId].subject = 'Prakarya (Kode 33)';
              const sched = DEFAULT_CLASS_SCHEDULE[cId];
              if (sched && state.classes[cId].sessions) {
                const offTime = `${sched.time} (${sched.hours})`;
                for (let p = 1; p <= 18; p++) {
                  if (state.classes[cId].sessions[p]) {
                    state.classes[cId].sessions[p].time = offTime;
                    state.classes[cId].sessions[p].day = sched.day;
                  }
                }
              }
            }
          });

          localStorage.setItem('partner_fatih_jurnal_state_v1', JSON.stringify(state));
        }

        if (typeof loadJurnalState === 'function') loadJurnalState();
        if (typeof initJurnalModule === 'function') initJurnalModule();
        summary.push('Jurnal: Kode 33 Prakarya & Jam Resmi Aktif');
      } catch (e) {
        console.warn('Gagal kalibrasi jurnal lokal:', e);
      }

      // 2. Cloud Sync Tab Jurnal dengan Supabase (Two-Way)
      try {
        if (typeof pullJurnalFromSupabase === 'function') {
          await pullJurnalFromSupabase(false);
          summary.push('Jurnal: Data Cloud Supabase Tersinkron');
        } else if (typeof syncJurnalToSupabase === 'function') {
          await syncJurnalToSupabase(false);
          summary.push('Jurnal: Data Cloud Tersimpan');
        }
      } catch (e) {
        console.warn('Cloud sync jurnal error:', e);
      }

      // 3. Sinkronisasi Tab Keuangan dengan Supabase
      try {
        if (typeof syncKeuanganWithSupabase === 'function') {
          await syncKeuanganWithSupabase(false);
          summary.push('Keuangan: Saldo & Mutasi Cloud Tersinkron');
        }
      } catch (e) {
        console.warn('Sync keuangan error:', e);
      }

      // 4. Sinkronisasi Tab Ruang Ide dengan Supabase (Two-Way AutoSync)
      try {
        if (typeof pullIdeFromCloud === 'function') {
          await pullIdeFromCloud(false);
          summary.push('Ruang Ide: Ide & Peluang Cloud Tersinkron');
        } else if (typeof syncIdeToCloud === 'function') {
          await syncIdeToCloud(false);
          summary.push('Ruang Ide: Data Cloud Tersimpan');
        }
      } catch (e) {
        console.warn('Sync ide cloud error:', e);
      }

      // 4. Periksa Pembaruan PWA Service Worker (App Update)
      try {
        if ('serviceWorker' in navigator) {
          const reg = await navigator.serviceWorker.getRegistration();
          if (reg) {
            await reg.update();
            if (reg.waiting) {
              reg.waiting.postMessage({ type: 'SKIP_WAITING' });
            }
          }
        }
      } catch (e) {
        console.warn('SW update check:', e);
      }

      // 5. Render Ulang Seluruh Komponen Aktif
      try {
        if (typeof renderKeuanganDashboard === 'function') renderKeuanganDashboard();
        if (typeof renderJurnalDashboard === 'function') renderJurnalDashboard();
        if (typeof renderJurnalTimetable === 'function') renderJurnalTimetable();
        if (typeof renderJurnalReminders === 'function') renderJurnalReminders();
        if (typeof renderJurnalClassCards === 'function') renderJurnalClassCards();
        if (typeof renderJurnalSessionCards === 'function') renderJurnalSessionCards();
        if (typeof safeCreateIcons === 'function') safeCreateIcons();
      } catch (e) {
        console.warn('Rerender error:', e);
      }

      if (icon) icon.classList.remove('animate-spin');
      if (btn) btn.disabled = false;

      const detailMsg = summary.length > 0 ? ('- ' + summary.join('\n- ')) : 'Seluruh modul telah diselaraskan.';
      
      if (typeof showToast === 'function') {
        showToast('Sinkronisasi Selesai', 'Semua tab & data cloud telah tersinkronkan.');
      }

      if (confirm('SEMUA TAB & CLOUD BERHASIL DISINKRONKAN!\n\n' + detailMsg + '\n\nSegarkan halaman sekarang agar tampilan HP langsung bersih dan terbarui?')) {
        window.location.reload();
      }
    };

    // ==========================================================================
        // ==========================================================================
    // PWA SEMANTIC VERSIONING & IN-APP AUTO-UPDATE ENGINE (v1.0.0)
    // ==========================================================================
    const CURRENT_APP_VERSION = '1.0.9';
    window.CURRENT_APP_VERSION = CURRENT_APP_VERSION;

    let pendingSwRegistration = null;
    let pendingSwWorker = null;
    let isPwaRefreshing = false;

    // Sinkronkan label versi di antarmuka UI
    function syncAppVersionUI() {
      try {
        const vBadges = document.querySelectorAll('#appVersionBadgeDrawer, #appVersionDrawerPill, #appVersionHeaderBadge, #appVersionDrawerLabel, .app-version-badge');
        vBadges.forEach(el => {
          if (el) el.textContent = `v${CURRENT_APP_VERSION}`;
        });
      } catch (e) {}
    }

    // Tampilkan Pop-Up Pembaruan Aplikasi Interaktif di Ponsel
    function showAppUpdateModal(newVer, changelogList) {
      try {
        const modal = document.getElementById('appUpdateModal');
        if (!modal) return;

        const curLabel = document.getElementById('updateModalCurrentVersion');
        if (curLabel) curLabel.textContent = `v${CURRENT_APP_VERSION}`;

        const newLabel = document.getElementById('updateModalNewVersion');
        if (newLabel) newLabel.textContent = newVer ? `v${newVer}` : 'Versi Baru';

        const btnLabel = document.getElementById('btnApplyPwaUpdateLabel');
        if (btnLabel) btnLabel.textContent = newVer ? `Perbarui ke v${newVer} Sekarang` : 'Perbarui Sekarang (1 Detik)';

        if (Array.isArray(changelogList) && changelogList.length > 0) {
          const ul = document.getElementById('updateModalChangelogList');
          if (ul) {
            ul.innerHTML = changelogList.map(c => `<li>${c}</li>`).join('');
          }
        }

        if (modal.parentElement !== document.body) {
          document.body.appendChild(modal);
        }
        modal.classList.remove('hidden');
        modal.style.display = 'flex';
        if (typeof safeCreateIcons === 'function') safeCreateIcons();
        if (typeof triggerHaptic === 'function') triggerHaptic();
      } catch (e) {
        console.warn('[PWA] Error showing update modal:', e);
      }
    }
    window.showAppUpdateModal = showAppUpdateModal;

    // Tutup Modal Pembaruan
    function dismissAppUpdateModal() {
      const modal = document.getElementById('appUpdateModal');
      if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
      }
    }
    window.dismissAppUpdateModal = dismissAppUpdateModal;

    // Eksekusi Pembaruan Instan (Skip Waiting -> Evict Old Cache -> Reload)
    function applyPwaUpdateNow() {
      const btn = document.getElementById('btnApplyPwaUpdate');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span class="inline-block animate-spin mr-1">🔄</span> Memperbarui...';
      }

      try {
        safeStorage.setItem('pwa_just_updated_to', '1');
      } catch (e) {}

      if (pendingSwWorker) {
        pendingSwWorker.postMessage({ type: 'SKIP_WAITING' });
      } else if (pendingSwRegistration && pendingSwRegistration.waiting) {
        pendingSwRegistration.waiting.postMessage({ type: 'SKIP_WAITING' });
      }

      // Fallback reload dalam 800ms jika controllerchange tidak terpicu
      setTimeout(() => {
        if (!isPwaRefreshing) {
          isPwaRefreshing = true;
          window.location.reload();
        }
      }, 800);
    }
    window.applyPwaUpdateNow = applyPwaUpdateNow;

    // Cek versi terbaru dari version.json di server
    async function checkForRemoteVersionUpdate() {
      try {
        if (!navigator.onLine) return;
        const res = await fetch('./version.json?_t=' + Date.now(), { cache: 'no-store' });
        if (res.ok) {
          const meta = await res.json();
          if (meta && meta.version && meta.version !== CURRENT_APP_VERSION) {
            console.log(`[PWA Update Found] Lokal: v${CURRENT_APP_VERSION} -> Server: v${meta.version}`);
            showAppUpdateModal(meta.version, meta.changelog);
          }
        }
      } catch (e) {
        // Safe offline skip
      }
    }

    if ('serviceWorker' in navigator && window.location.protocol.startsWith('http')) {
      const initServiceWorkerLifecycle = () => {
        navigator.serviceWorker.register('./sw.js', { scope: './' }).then(reg => {
          pendingSwRegistration = reg;
          console.log(`[PWA v${CURRENT_APP_VERSION}] ServiceWorker terdaftar aktif:`, reg.scope);

          // Jika ada Service Worker yang sedang menunggu aktif (Waiting Worker)
          if (reg.waiting) {
            pendingSwWorker = reg.waiting;
            checkForRemoteVersionUpdate();
          }

          // Deteksi event pembaruan baru dari Service Worker
          reg.addEventListener('updatefound', () => {
            const newWorker = reg.installing;
            if (!newWorker) return;

            newWorker.addEventListener('statechange', () => {
              if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                pendingSwWorker = newWorker;
                console.log('[PWA] Versi baru aplikasi berhasil diunduh di latar belakang!');
                checkForRemoteVersionUpdate();
              }
            });
          });

          // Cek update otomatis saat kembali ke aplikasi (Visibility Change)
          document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible') {
              reg.update().catch(() => {});
              checkForRemoteVersionUpdate();
              if (typeof pullKeuanganFromCloud === 'function') pullKeuanganFromCloud(false);
            }
          });

          // Cek berkala setiap 5 menit saat online
          setInterval(() => {
            reg.update().catch(() => {});
            checkForRemoteVersionUpdate();
          }, 5 * 60 * 1000);

        }).catch(err => {
          console.warn('[PWA] Catatan pendaftaran ServiceWorker (aman):', err);
        });
      };

      // Mulus reload otomatis saat Service Worker baru mengambil alih
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        if (isPwaRefreshing) return;
        isPwaRefreshing = true;
        window.location.reload();
      });

      if (document.readyState === 'complete') {
        initServiceWorkerLifecycle();
      } else {
        window.addEventListener('load', initServiceWorkerLifecycle);
      }
    }

    // Notifikasi selebrasi setelah update berhasil dipasang
    window.addEventListener('DOMContentLoaded', () => {
      syncAppVersionUI();
      try {
        if (safeStorage.getItem('pwa_just_updated_to') === '1') {
          safeStorage.removeItem('pwa_just_updated_to');
          setTimeout(() => {
            if (typeof showToast === 'function') {
              showToast(`Aplikasi Diperbarui 🎉`, `Versi ${CURRENT_APP_VERSION} aktif sempurna tanpa install ulang.`);
            }
          }, 600);
        }
      } catch (e) {}
    });

    // Fungsi Global: Cek Pembaruan Manual (Diakses lewat menu Drawer atau tombol Master Sync)
    window.forceCheckAppUpdate = function(isUserTriggered = true) {
      if (isUserTriggered && typeof showToast === 'function') {
        showToast('Memeriksa Pembaruan...', 'Menghubungkan ke server Vercel...');
      }

      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(async regs => {
          let hasUpdate = false;
          if (regs && regs.length > 0) {
            await Promise.all(regs.map(r => r.update().catch(() => {})));
            for (let r of regs) {
              if (r.waiting) {
                pendingSwWorker = r.waiting;
                hasUpdate = true;
                break;
              }
            }
          }

          // Cek juga version.json
          try {
            const res = await fetch('./version.json?_t=' + Date.now(), { cache: 'no-store' });
            if (res.ok) {
              const meta = await res.json();
              if (meta && meta.version && meta.version !== CURRENT_APP_VERSION) {
                hasUpdate = true;
                showAppUpdateModal(meta.version, meta.changelog);
                return;
              }
            }
          } catch (e) {}

          if (hasUpdate) {
            showAppUpdateModal();
          } else if (isUserTriggered) {
            if (typeof showToast === 'function') {
              showToast('Aplikasi Sudah Versi Terbaru', `Versi ${CURRENT_APP_VERSION} sudah yang paling mutakhir.`);
            }
          }
        }).catch(() => {
          if (isUserTriggered && typeof showToast === 'function') {
            showToast('Aplikasi Versi Aktif', `Versi ${CURRENT_APP_VERSION} berjalan normal.`);
          }
        });
      } else {
        if (isUserTriggered && typeof showToast === 'function') {
          showToast('Aplikasi Versi Aktif', `Versi ${CURRENT_APP_VERSION} berjalan normal.`);
        }
      }
    };

