                onkeydown="if(event.key === 'Enter' && (event.ctrlKey || !event.shiftKey)) { event.preventDefault(); saveInlineEditHumasTask('${t.id}'); } else if(event.key === 'Escape') { cancelInlineEditHumasTask(); }"
                class="w-full p-2.5 rounded-lg border-2 border-amber-300 dark:border-amber-700 bg-white dark:bg-slate-900 text-xs sm:text-sm font-bold text-slate-900 dark:text-white focus:outline-none focus:border-amber-500 focus:ring-2 focus:ring-amber-500/30 leading-relaxed shadow-inner"
                placeholder="Tuliskan uraian tugas kegiatan Anda..."
