    classData.students = lines.map((name, idx) => ({
      id: `${classData.label}-${idx + 1}`,
      name: name,
      gender: idx % 2 === 0 ? 'L' : 'P',
      bonusActive: 10,
      pureSts: 75,
      pureSas: 78
    }));

    saveJurnalState();
    closeManageStudentsModal();
    renderPresensiTable();
