    if (elYear) elYear.textContent = `TAHUN PELAJARAN ${window.cbtState.metadata.academic_year || "2026/2027"}`;
    if (elSubj) elSubj.textContent = (window.cbtState.metadata.subject || "PRAKARYA 7").toUpperCase();
