    if (elCityDate) elCityDate.textContent = `${window.cbtState.metadata.city || "Lamongan"}, ${curDateRemidi}`;
    if (elAuthor) elAuthor.textContent = window.cbtState.metadata.author || "Mohammad Ilham Mahmudi";

