    // --- MODAL PORTAL HELPER ---
    function portalAllModalsToBody() {
      try {
        var modals = document.querySelectorAll('[id^="modal"], .modal-portal');
        for (var m = 0; m < modals.length; m++) {
          var el = modals[m];
          if (el && el.parentElement && el.parentElement !== document.body && el.classList.contains('fixed')) {
            document.body.appendChild(el);
          }
        }
      } catch (e) {
        console.warn('Portal modals error:', e);
      }
    }
    window.portalAllModalsToBody = portalAllModalsToBody;

    function initializeApp() {
      // Pastikan iframe window tidak tergeser ke bawah (mencegah bagian atas terpotong di Apps Script)
      try {
        if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
        window.scrollTo(0, 0);
        if (document.documentElement) document.documentElement.scrollTop = 0;
        if (document.body) document.body.scrollTop = 0;
        const mc = document.getElementById('mainCanvas');
        if (mc) mc.scrollTop = 0;
      } catch (e) {}

      try { portalAllModalsToBody(); } catch(e) {}
      try { applySavedTheme(); } catch (e) { console.warn('Theme init error:', e); }
      try { safeCreateIcons(); } catch (e) { console.warn('Icon init error:', e); }
      try { initScrollInteraction(); } catch (e) { console.warn('Scroll interaction init error:', e); }
      try { initDockWheelInteraction(); } catch (e) { console.warn('Dock wheel error:', e); }
      try { initRoomPillsWheelInteraction(); } catch (e) { console.warn('Room pills wheel error:', e); }
      try { initUniversalWheelScroll(); } catch (e) { console.warn('Universal wheel scroll error:', e); }
      try { initMobileSwipeGestures(); } catch (e) { console.warn('Mobile swipe error:', e); }
      // INSTANT SAT-SET: Buka langsung tab aktif tanpa menunda
      const urlParams = new URLSearchParams(window.location.search);
      const initialTab = urlParams.get('tab') || localStorage.getItem('partner_fatih_last_tab') || 'humas';
      window.appRootTab = initialTab;
      try { switchTab(initialTab); } catch (e) { console.warn('Tab init error:', e); }
      
      const initialSubtab = urlParams.get('subtab');
      if (initialSubtab && typeof switchPpdbSubtab === 'function') {
        try { switchPpdbSubtab(initialSubtab); } catch(e) {}
      }
      if (urlParams.get('sample') === '1') {
        try { loadPpdbSampleData(); } catch(e) {}
      }

      // Siapkan modul inti & data master tuntas di balik layar loading
      const statusText = document.getElementById('preloaderStatusText');
      if (statusText) statusText.textContent = 'Memuat modul & master data...';

      try { renderBrivaMonthPills(); } catch (e) {}
      try { calculateSingleReceipt(); } catch (e) {}
      try { runAccountGenerator(); } catch (e) {}
      try { runBrivaGenerator(); } catch (e) {}
      try { initTahfidzModule(); } catch (e) {}
      try { if (initialTab !== 'humas') initHumasModule(); } catch (e) {}
      try { updateHumasNotifButtonUI(); } catch (e) {}
      try { checkHumasH7MobileNotifications(); } catch (e) {}
      try { if (initialTab !== 'jurnal') initJurnalModule(); } catch (e) {}
      try { if (initialTab !== 'keuangan') initKeuanganModule(); } catch (e) {}
      try { if (initialTab !== 'cbt' && typeof window.initCbtTab === 'function') window.initCbtTab(); } catch (e) {}
      try { if (initialTab !== 'ide' && typeof window.initIdeTab === 'function') window.initIdeTab(); } catch (e) {}
      try { renderPpdbAll(); } catch (e) {}
      try { togglePpdbViewMode(window.innerWidth < 640 ? 'cards' : 'table'); } catch (e) {}

      // Pastikan semua ikon 100% menyala sempurna
      safeCreateIcons();

      // Tutup loading screen secara mulus: aplikasi kini 100% tuntas & siap digunakan
      if (typeof window.dismissAppPreloader === 'function') {
        window.dismissAppPreloader();
      }
      try { updateLiveClock(); } catch (e) { console.warn('Clock init error:', e); }
      try { initSmartBackNavigation(); } catch (e) { console.warn('Back nav init error:', e); }
      
      try { setInterval(updateLiveClock, 1000); } catch (e) {}



      // PWA Service Worker Registration (100% Offline Engine)
      try {
        if ('serviceWorker' in navigator && window.location.protocol.startsWith('http')) {
          navigator.serviceWorker.register('./sw.js')
            .then(function(reg) {
              console.log('[PWA] Service Worker aktif & siap 100% offline:', reg.scope);
            })
            .catch(function(err) {
              console.warn('[PWA] Service Worker error (safe to continue):', err);
            });
        }
      } catch (e) {}

      // Sat-Set Instant Ready: Render ikon secara instan & tanpa jeda
      safeCreateIcons();
      if (typeof window.dismissAppPreloader === 'function') window.dismissAppPreloader();
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initializeApp);
    } else {
      initializeApp();
    }
    window.addEventListener('load', () => { safeCreateIcons(); if (typeof window.dismissAppPreloader === 'function') window.dismissAppPreloader(); });


